"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def unnamed_function(head):
    slow = head
    fast = head
    while ((fast is not None) and (fast.next is not None)):
        slow = slow.next
        fast = fast.next.next
        if (slow == fast):
            return True
    return False

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None


# Build a linked list: 1 → 2 → 3 → 4 → 5
head = Node(1)
head.next = Node(2)
head.next.next = Node(3)
head.next.next.next = Node(4)
head.next.next.next.next = Node(5)

# Create a cycle: node 5 → node 3
head.next.next.next.next.next = head.next.next

print(unnamed_function(head))   # True


# Break the cycle
head.next.next.next.next.next = None

print(unnamed_function(head))   # False
